CREATE TABLE EquipeManutencao (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR2(100), especialidade VARCHAR2(50));
CREATE TABLE TrechoRodovia (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, rodovia VARCHAR2(50), km_inicial NUMBER, km_final NUMBER, nivel_risco VARCHAR2(20));
CREATE TABLE RelatorioPrioridade (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, resumo VARCHAR2(500), data_geracao TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
